select * from TBL_TESTPLAN where 1=1

	AND planname LIKE concat(concat('%',#{queryParam.planname}),'%')


	AND plannumber LIKE concat(concat('%',#{queryParam.plannumber}),'%')


	AND planyear LIKE concat(concat('%',#{queryParam.planyear}),'%')


	AND planstatus LIKE concat(concat('%',#{queryParam.planstatus}),'%')


	and starttime >=#{queryParam.starttime}


	and endtime <=#{queryParam.endtime}



	and orgid IN

		#{item}




	${sql}

order by testplanid desc

select * from TBL_TESTPLAN where 1=1

	AND planname LIKE concat(concat('%',#{queryParam.planname}),'%')


	AND plannumber LIKE concat(concat('%',#{queryParam.plannumber}),'%')


	AND planyear LIKE concat(concat('%',#{queryParam.planyear}),'%')


	AND planstatus LIKE concat(concat('%',#{queryParam.planstatus}),'%')


	and starttime >=#{queryParam.starttime}


	and endtime <=#{queryParam.endtime}



	${sql}

order by testplanid desc

SELECT DISTINCT pl.* from TBL_TESTPLAN pl LEFT JOIN TBL_TESTTASK task
on PL.TESTPLANID=TASK.PLANID
where PL.PLANSTATUS!='未启动' AND
TASK.COMPLETESTAUS <>1 and
TASK.CPUSERID=#{queryParam.creatid}

	and (pl.ORGID in

		#{item}

	OR pl.ORGID =#{queryParam.orgid}
	)



	${sql}

order by pl.TESTPLANID

SELECT DISTINCT * from TBL_TESTPLAN te WHERE TE.PLANSTATUS!='已完成' and TE.PLANSTATUS!='未启动'
and TE.ORGID in ( select ORGID from TBL_ORGANIZATION where (FATHERORGID=#{queryParam.orgid} AND ORGTYPE=0 or ORGID=#{queryParam.orgid}))
AND planname LIKE concat(concat('%',#{queryParam.planname}),'%')
AND plannumber LIKE concat(concat('%',#{queryParam.plannumber}),'%')
AND planyear LIKE concat(concat('%',#{queryParam.planyear}),'%')
AND planstatus LIKE concat(concat('%',#{queryParam.planstatus}),'%')
and endtime <=#{queryParam.endtime}
and starttime >=#{queryParam.starttime}
${sql}
ORDER BY TESTPLANID desc

SELECT * FROM TBL_TESTPLAN pl WHERE PL.PLANSTATUS!='已完成' and
PL.PLANSTATUS!='未启动'


	AND planname LIKE concat(concat('%',#{queryParam.planname}),'%')


	AND plannumber LIKE concat(concat('%',#{queryParam.plannumber}),'%')


	AND planyear LIKE concat(concat('%',#{queryParam.planyear}),'%')


	AND planstatus LIKE concat(concat('%',#{queryParam.planstatus}),'%')


	and starttime >=#{queryParam.starttime}


	and endtime <=#{queryParam.endtime}


	${sql}

ORDER BY TESTPLANID desc
